<?php $skippedRows=session()->getFlashdata('skipped_rows'); if (!empty($skippedRows)): ?><section class="card border-0 shadow-sm"><div class="card-header bg-white py-3"><h2 class="h6 mb-0"><i class="fa fa-list-check me-2 text-warning"></i>Data yang dilewati</h2></div><div class="table-responsive"><table class="table table-sm table-striped table-bordered align-middle mb-0"><thead><tr><th>Baris</th><th>VA</th><th>Nama</th><th>Referensi</th><th>Nominal</th><th>Tanggal</th><th>Alasan</th></tr></thead><tbody><?php foreach ($skippedRows as $item): ?><tr><td><?= esc($item['row']) ?></td><td><?= esc($item['va']) ?></td><td><?= esc($item['nama']) ?></td><td><?= esc($item['ref']) ?></td><td><?= esc($item['nominal']) ?></td><td><?= esc($item['tanggal']) ?></td><td><?= esc($item['reason']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?></main>
<script>
const csvInput=document.getElementById('csv'),fileName=document.getElementById('fileName'),uploadBox=document.querySelector('.upload-box');csvInput?.addEventListener('change',()=>{fileName.textContent=csvInput.files[0]?.name||''});['dragenter','dragover'].forEach(n=>uploadBox?.addEventListener(n,e=>{e.preventDefault();uploadBox.classList.add('dragover')}));['dragleave','drop'].forEach(n=>uploadBox?.addEventListener(n,e=>{e.preventDefault();uploadBox.classList.remove('dragover')}));uploadBox?.addEventListener('drop',e=>{if(e.dataTransfer.files.length){csvInput.files=e.dataTransfer.files;fileName.textContent=csvInput.files[0].name}});
</script>
